53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
107	        this.clinicService.createOwner(owner, sharesHousehold);
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        headers.setLocation(UriComponentsBuilder.newInstance()
110	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
111	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
117	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
118	        if (currentOwner == null) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        currentOwner.setAddress(ownerFieldsDto.getAddress());
122	        currentOwner.setCity(ownerFieldsDto.getCity());
123	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
124	        currentOwner.setLastName(ownerFieldsDto.getLastName());
125	        currentOwner.setTelephone(TelephoneNormalizer.toE164(ownerFieldsDto.getTelephone()).orElse(null));
126	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
127	        this.clinicService.saveOwner(currentOwner);
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Transactional
133	    @Override
134	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        this.clinicService.deleteOwner(owner);
140	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
146	        Owner owner = this.clinicService.findOwnerById(ownerId);
147	        if (owner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        HttpHeaders headers = new HttpHeaders();
151	        Pet pet = petMapper.toPet(petFieldsDto);
152	        owner.setId(ownerId);
153	        pet.setOwner(owner);
154	        pet.getType().setName(null);
155	        this.clinicService.savePet(pet);
156	        PetDto petDto = petMapper.toPetDto(pet);
157	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
158	            .buildAndExpand(pet.getId()).toUri());
159	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner != null) {
167	            Pet currentPet = this.clinicService.findPetById(petId);
168	            if (currentPet != null) {
169	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
170	                currentPet.setName(petFieldsDto.getName());
171	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
172	                this.clinicService.savePet(currentPet);
173	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
174	            }
175	        }
176	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
182	        HttpHeaders headers = new HttpHeaders();
183	        Visit visit = visitMapper.toVisit(visitFieldsDto);
184	        Pet pet = new Pet();
185	        pet.setId(petId);
186	        visit.setPet(pet);
187	        this.clinicService.saveVisit(visit);
188	        VisitDto visitDto = visitMapper.toVisitDto(visit);
189	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
190	            .buildAndExpand(visit.getId()).toUri());
191	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
192	    }
193	
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner != null) {
200	            Pet pet = owner.getPet(petId);
201	            if (pet != null) {
202	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	}
