259	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
260	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
261	        }
262	        if (owner.getRegistrationDate() == null) {
263	            owner.setRegistrationDate(LocalDate.now());
264	        }
265	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
266	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
267	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
268	        }
269	        owner.setNamesakeCount(countNamesakes(owner));
270	        owner.setCustomerCode(CustomerCodeGenerator.format(
271	            owner.getCity(), owner.getLastName(), ownersInCity + 1));
272	        if (!householdMembers.isEmpty()) {
273	            owner.setHouseholdId(joinHousehold(owner, householdMembers));
274	        }
275	        ownerRepository.save(owner);
276	        return owner.getHouseholdId();
277	    }
278	
279	    /**
280	     * Assign the stable household identifier to the new owner and to every existing member of the
281	     * household, persisting the members whose identifier changes, and return the shared identifier.
282	     */
283	    private String joinHousehold(Owner owner, List<Owner> householdMembers) {
284	        String householdId = HouseholdIdGenerator.generate(owner.getLastName(), owner.getAddress());
285	        for (Owner member : householdMembers) {
286	            if (!householdId.equals(member.getHouseholdId())) {
287	                member.setHouseholdId(householdId);
288	                ownerRepository.save(member);
289	            }
290	        }
291	        return householdId;
292	    }
293	
294	    @Override
295	    @Transactional
296	    public void saveOwner(Owner owner) throws DataAccessException {
297	        ownerRepository.save(owner);
298	    }
299	
300	    /**
301	     * Count the owners that already exist sharing this owner's first name and last name, compared
302	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
303	     */
304	    private int countNamesakes(Owner owner) {
305	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
306	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
307	            .count();
308	    }
309	
310	    /**
311	     * Find the existing owners that already share this owner's household, i.e. that have the same last name and
312	     * address compared case-insensitively and with runs of whitespace collapsed.
313	     */
314	    private List<Owner> findHouseholdMembers(Owner owner) {
315	        String address = TextNormalizer.normalize(owner.getAddress());
316	        if (address == null) {
317	            return List.of();
318	        }
319	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
320	            .filter(existing -> address.equals(TextNormalizer.normalize(existing.getAddress())))
321	            .toList();
322	    }
323	
324	    @Override
325	    @Transactional(readOnly = true)
326	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
327	        return ownerRepository.findByLastName(lastName);
328	    }
329	
330	    @Override
331	    @Transactional(readOnly = true)
332	    public Collection<Visit> findVisitsByPetId(int petId) {
333	        return visitRepository.findByPetId(petId);
334	    }
335	
336	    @Override
337	    @Transactional(readOnly = true)
338	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
339	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
340	    }
341	
342	    private <T> T findEntityById(Supplier<T> supplier) {
343	        try {
344	            return supplier.get();
345	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
346	            // Just ignore not found exceptions for Jdbc/Jpa realization
347	            return null;
348	        }
349	    }
350	
351	}
